mod config;
mod sensors;

use config::Config;
use rppal::gpio::Gpio;
use rumqttc::{Client, Event, MqttOptions, Packet, QoS};
use std::error::Error;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

fn main() {
    if let Err(e) = run() {
        eprintln!("Fehler: {e}");
        std::process::exit(1);
    }
}

fn run() -> Result<(), Box<dyn Error>> {
    let pfad = std::env::args().nth(1).unwrap_or_else(|| "config.toml".into());
    let cfg = Config::laden(&pfad)?;

    // Sensoren initialisieren
    let gpio = Gpio::new().map_err(|e| format!("GPIO nicht verfügbar: {e}"))?;
    let mut sensoren = Vec::new();
    for sc in cfg.sensoren {
        let s = sc.bauen(&gpio)?;
        println!("Sensor bereit: {}", s.name());
        sensoren.push(s);
    }

    // MQTT verbinden
    let mut opts = MqttOptions::new(&cfg.mqtt.client_id, &cfg.mqtt.host, cfg.mqtt.port);
    opts.set_keep_alive(Duration::from_secs(30));
    if let (Some(u), Some(p)) = (&cfg.mqtt.benutzer, &cfg.mqtt.passwort) {
        opts.set_credentials(u, p);
    }
    let (client, mut verbindung) = Client::new(opts, 100);

    // Netzwerk-Eventloop im Hintergrund, verbindet bei Abbruch automatisch neu
    let broker = format!("{}:{}", cfg.mqtt.host, cfg.mqtt.port);
    thread::spawn(move || {
        for ereignis in verbindung.iter() {
            match ereignis {
                Ok(Event::Incoming(Packet::ConnAck(_))) => println!("MQTT verbunden mit {broker}"),
                Ok(_) => {}
                Err(e) => {
                    eprintln!("MQTT-Verbindungsfehler: {e} – neuer Versuch in 5 s");
                    thread::sleep(Duration::from_secs(5));
                }
            }
        }
    });

    let intervall = Duration::from_secs(cfg.intervall_s);
    loop {
        for sensor in sensoren.iter_mut() {
            let topic = format!("{}/{}", cfg.mqtt.topic_prefix, sensor.name());
            match sensor.lesen() {
                Ok(mut wert) => {
                    if let Some(obj) = wert.as_object_mut() {
                        obj.insert("zeit".into(), unix_zeit().into());
                    }
                    let payload = wert.to_string();
                    println!("{topic} {payload}");
                    // try_publish blockiert nicht, falls der Broker gerade weg ist
                    if let Err(e) = client.try_publish(&topic, QoS::AtLeastOnce, false, payload) {
                        eprintln!("{topic}: nicht gesendet ({e})");
                    }
                }
                Err(e) => eprintln!("{topic}: Lesefehler: {e}"),
            }
        }
        thread::sleep(intervall);
    }
}

fn unix_zeit() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

