use crate::sensors::SensorConfig;
use serde::Deserialize;
use std::error::Error;
use std::fs;

#[derive(Debug, Deserialize)]
pub struct Config {
    pub mqtt: MqttConfig,
    /// Sekunden zwischen zwei Auslese-Runden
    #[serde(default = "standard_intervall")]
    pub intervall_s: u64,
    #[serde(default, rename = "sensor")]
    pub sensoren: Vec<SensorConfig>,
}

#[derive(Debug, Deserialize)]
pub struct MqttConfig {
    pub host: String,
    #[serde(default = "standard_port")]
    pub port: u16,
    #[serde(default = "standard_client_id")]
    pub client_id: String,
    /// Messwerte landen unter `<topic_prefix>/<sensorname>`
    #[serde(default = "standard_prefix")]
    pub topic_prefix: String,
    pub benutzer: Option<String>,
    pub passwort: Option<String>,
}

fn standard_intervall() -> u64 {
    5
}
fn standard_port() -> u16 {
    1883
}
fn standard_client_id() -> String {
    "pi5-sensoren".into()
}
fn standard_prefix() -> String {
    "pi5".into()
}

impl Config {
    pub fn laden(pfad: &str) -> Result<Self, Box<dyn Error>> {
        let text = fs::read_to_string(pfad)
            .map_err(|e| format!("Konfiguration '{pfad}' nicht lesbar: {e}"))?;
        let cfg: Config =
            toml::from_str(&text).map_err(|e| format!("Fehler in '{pfad}': {e}"))?;
        if cfg.sensoren.is_empty() {
            return Err(format!("In '{pfad}' ist kein [[sensor]] eingetragen").into());
        }
        Ok(cfg)
    }
}

