//! Ultraschall-Abstandssensor HC-SR04.
//!
//! Ablauf einer Messung:
//! 1. Trigger-Pin für mindestens 10 µs auf HIGH setzen.
//! 2. Der Sensor sendet 8 Ultraschallpulse und setzt Echo auf HIGH,
//!    bis das reflektierte Signal zurückkommt.
//! 3. Die Dauer des Echo-Pulses entspricht der doppelten Laufstrecke.
//!
//! Die Pulsdauer wird über GPIO-Interrupts gemessen. Die Zeitstempel kommen
//! dabei direkt vom Kernel und sind deutlich genauer als Abfragen in einer
//! Schleife (Polling), bei der der Linux-Scheduler dazwischenfunken kann.

use super::{Messwert, Sensor};
use rppal::gpio::{Event, Gpio, InputPin, OutputPin, Trigger};
use serde::Deserialize;
use serde_json::json;
use std::error::Error;
use std::thread;
use std::time::{Duration, Instant};

/// Ohne Objekt in Reichweite liefert der Sensor nach ca. 38 ms ein Echo.
const ECHO_TIMEOUT: Duration = Duration::from_millis(60);
/// Laut Datenblatt mindestens 60 ms zwischen zwei Messungen.
const PAUSE_ZWISCHEN_MESSUNGEN: Duration = Duration::from_millis(60);
/// Messbereich laut Datenblatt.
const MIN_CM: f64 = 2.0;
const MAX_CM: f64 = 400.0;

#[derive(Debug, Deserialize)]
pub struct Config {
    pub name: String,
    /// BCM-Nummer des Trigger-Pins (z. B. 23 = physischer Pin 16)
    pub trigger_pin: u8,
    /// BCM-Nummer des Echo-Pins (z. B. 24 = physischer Pin 18)
    pub echo_pin: u8,
    /// Anzahl Einzelmessungen pro Auslesung; gemeldet wird der Median.
    #[serde(default = "standard_messungen")]
    pub messungen: usize,
    /// Lufttemperatur in °C für die Schallgeschwindigkeit.
    #[serde(default = "standard_temperatur")]
    pub temperatur_c: f64,
}

fn standard_messungen() -> usize {
    5
}

fn standard_temperatur() -> f64 {
    20.0
}

pub struct HcSr04 {
    name: String,
    trigger: OutputPin,
    echo: InputPin,
    messungen: usize,
    schall_m_pro_s: f64,
}

impl HcSr04 {
    pub fn new(gpio: &Gpio, cfg: Config) -> Result<Self, Box<dyn Error>> {
        let trigger = gpio.get(cfg.trigger_pin)?.into_output_low();
        let mut echo = gpio.get(cfg.echo_pin)?.into_input();
        echo.set_interrupt(Trigger::Both, None)?;

        Ok(Self {
            name: cfg.name,
            trigger,
            echo,
            messungen: cfg.messungen.max(1),
            schall_m_pro_s: schallgeschwindigkeit(cfg.temperatur_c),
        })
    }

    /// Eine einzelne Messung, Ergebnis in cm.
    fn ping(&mut self) -> Result<f64, Box<dyn Error>> {
        // Liegengebliebene Ereignisse aus früheren Messungen verwerfen.
        self.echo.poll_interrupt(true, Some(Duration::ZERO))?;

        // Trigger-Puls (>= 10 µs). Aktives Warten, weil sleep() so kurze
        // Zeiten nicht zuverlässig einhält.
        self.trigger.set_high();
        let start = Instant::now();
        while start.elapsed() < Duration::from_micros(12) {
            std::hint::spin_loop();
        }
        self.trigger.set_low();

        let deadline = Instant::now() + ECHO_TIMEOUT;
        let steigend = self.warte_auf(Trigger::RisingEdge, deadline)?;
        let fallend = self.warte_auf(Trigger::FallingEdge, deadline)?;

        let puls = fallend
            .timestamp
            .checked_sub(steigend.timestamp)
            .ok_or("ungültige Zeitstempel")?;

        let cm = abstand_cm(puls, self.schall_m_pro_s);
        if !(MIN_CM..=MAX_CM).contains(&cm) {
            return Err(format!("außerhalb des Messbereichs ({cm:.1} cm)").into());
        }
        Ok(cm)
    }

    fn warte_auf(&mut self, gesucht: Trigger, deadline: Instant) -> Result<Event, Box<dyn Error>> {
        loop {
            let rest = deadline.saturating_duration_since(Instant::now());
            if rest.is_zero() {
                return Err(timeout_fehler(gesucht));
            }
            match self.echo.poll_interrupt(false, Some(rest))? {
                Some(ev) if ev.trigger == gesucht => return Ok(ev),
                Some(_) => continue, // unerwartete Flanke, ignorieren
                None => return Err(timeout_fehler(gesucht)),
            }
        }
    }
}

fn timeout_fehler(gesucht: Trigger) -> Box<dyn Error> {
    if gesucht == Trigger::RisingEdge {
        "kein Echo-Signal – Verkabelung, Spannungsteiler und 5-V-Versorgung prüfen".into()
    } else {
        "Echo-Puls endet nicht (Timeout)".into()
    }
}

impl Sensor for HcSr04 {
    fn name(&self) -> &str {
        &self.name
    }

    fn lesen(&mut self) -> Result<Messwert, Box<dyn Error>> {
        let mut werte = Vec::with_capacity(self.messungen);
        let mut letzter_fehler = None;

        for i in 0..self.messungen {
            if i > 0 {
                thread::sleep(PAUSE_ZWISCHEN_MESSUNGEN);
            }
            match self.ping() {
                Ok(cm) => werte.push(cm),
                Err(e) => letzter_fehler = Some(e),
            }
        }

        let abstand = match median(&mut werte) {
            Some(m) => m,
