//! Gemeinsame Schnittstelle für alle Sensoren.
//!
//! Neuen Sensor hinzufügen:
//! 1. Datei `src/sensors/<name>.rs` mit einer `Config` und einem Typ anlegen,
//!    der das Trait `Sensor` implementiert (Vorlage: `hcsr04.rs`).
//! 2. Unten `mod <name>;` ergänzen und eine Variante in `SensorConfig`
//!    sowie einen Zweig in `SensorConfig::bauen` hinzufügen.
//! 3. In `config.toml` einen `[[sensor]]`-Block mit `typ = "<name>"` eintragen.

mod hcsr04;

use rppal::gpio::Gpio;
use serde::Deserialize;
use std::error::Error;

/// Messwerte eines Sensors als JSON-Objekt, z. B. `{"abstand_cm": 42.3}`.
pub type Messwert = serde_json::Value;

pub trait Sensor {
    /// Eindeutiger Name, wird auch als MQTT-Topic verwendet.
    fn name(&self) -> &str;
    /// Liest den Sensor aus und gibt die Messwerte zurück.
    fn lesen(&mut self) -> Result<Messwert, Box<dyn Error>>;
}

/// Ein `[[sensor]]`-Eintrag aus der config.toml.
/// Das Feld `typ` entscheidet, welcher Sensor gebaut wird.
#[derive(Debug, Deserialize)]
#[serde(tag = "typ", rename_all = "lowercase")]
pub enum SensorConfig {
    Hcsr04(hcsr04::Config),
    // Später z. B.:
    // Bme280(bme280::Config),
    // Ds18b20(ds18b20::Config),
}

impl SensorConfig {
    pub fn bauen(self, gpio: &Gpio) -> Result<Box<dyn Sensor>, Box<dyn Error>> {
        Ok(match self {
            SensorConfig::Hcsr04(cfg) => Box::new(hcsr04::HcSr04::new(gpio, cfg)?),
        })
    }
}

