18	fn run() -> Result<(), Box<dyn Error>> {
19	    let pfad = std::env::args().nth(1).unwrap_or_else(|| "config.toml".into());
20	    let cfg = Config::laden(&pfad)?;
21	
22	    // Sensoren initialisieren
23	    let gpio = Gpio::new().map_err(|e| format!("GPIO nicht verfügbar: {e}"))?;
24	    let mut sensoren = Vec::new();
25	    for sc in cfg.sensoren {
26	        let s = sc.bauen(&gpio)?;
27	        println!("Sensor bereit: {}", s.name());
28	        sensoren.push(s);
29	    }
30	
31	    // MQTT verbinden
32	    let mut opts = MqttOptions::new(&cfg.mqtt.client_id, &cfg.mqtt.host, cfg.mqtt.port);
33	    opts.set_keep_alive(Duration::from_secs(30));
34	    if let (Some(u), Some(p)) = (&cfg.mqtt.benutzer, &cfg.mqtt.passwort) {
35	        opts.set_credentials(u, p);
36	    }
37	    let (client, mut verbindung) = Client::new(opts, 100);
38	
39	    // Netzwerk-Eventloop im Hintergrund, verbindet bei Abbruch automatisch neu
40	    let broker = format!("{}:{}", cfg.mqtt.host, cfg.mqtt.port);
41	    thread::spawn(move || {
42	        for ereignis in verbindung.iter() {
43	            match ereignis {
44	                Ok(Event::Incoming(Packet::ConnAck(_))) => println!("MQTT verbunden mit {broker}"),
45	                Ok(_) => {}
46	                Err(e) => {
47	                    eprintln!("MQTT-Verbindungsfehler: {e} – neuer Versuch in 5 s");
48	                    thread::sleep(Duration::from_secs(5));
49	                }
50	            }
51	        }
52	    });
53	
54	    let intervall = Duration::from_secs(cfg.intervall_s);
55	    loop {
56	        for sensor in sensoren.iter_mut() {
57	            let topic = format!("{}/{}", cfg.mqtt.topic_prefix, sensor.name());
58	            match sensor.lesen() {
59	                Ok(mut wert) => {
60	                    if let Some(obj) = wert.as_object_mut() {
61	                        obj.insert("zeit".into(), unix_zeit().into());
62	                    }
63	                    let payload = wert.to_string();
64	                    println!("{topic} {payload}");
65	                    // try_publish blockiert nicht, falls der Broker gerade weg ist
66	                    if let Err(e) = client.try_publish(&topic, QoS::AtLeastOnce, false, payload) {
67	                        eprintln!("{topic}: nicht gesendet ({e})");
68	                    }
69	                }
70	                Err(e) => eprintln!("{topic}: Lesefehler: {e}"),
71	            }
72	        }
73	        thread::sleep(intervall);
74	    }
75	}
