2	//!
3	//! Ablauf einer Messung:
4	//! 1. Trigger-Pin für mindestens 10 µs auf HIGH setzen.
5	//! 2. Der Sensor sendet 8 Ultraschallpulse und setzt Echo auf HIGH,
6	//!    bis das reflektierte Signal zurückkommt.
7	//! 3. Die Dauer des Echo-Pulses entspricht der doppelten Laufstrecke.
8	//!
9	//! Die Pulsdauer wird über GPIO-Interrupts gemessen. Die Zeitstempel kommen
10	//! dabei direkt vom Kernel und sind deutlich genauer als Abfragen in einer
11	//! Schleife (Polling), bei der der Linux-Scheduler dazwischenfunken kann.
12	
13	use super::{Messwert, Sensor};
14	use rppal::gpio::{Event, Gpio, InputPin, OutputPin, Trigger};
15	use serde::Deserialize;
16	use serde_json::json;
17	use std::error::Error;
18	use std::thread;
19	use std::time::{Duration, Instant};
20	
21	/// Ohne Objekt in Reichweite liefert der Sensor nach ca. 38 ms ein Echo.
22	const ECHO_TIMEOUT: Duration = Duration::from_millis(60);
23	/// Laut Datenblatt mindestens 60 ms zwischen zwei Messungen.
24	const PAUSE_ZWISCHEN_MESSUNGEN: Duration = Duration::from_millis(60);
25	/// Messbereich laut Datenblatt.
26	const MIN_CM: f64 = 2.0;
27	const MAX_CM: f64 = 400.0;
28	
29	#[derive(Debug, Deserialize)]
30	pub struct Config {
31	    pub name: String,
32	    /// BCM-Nummer des Trigger-Pins (z. B. 23 = physischer Pin 16)
33	    pub trigger_pin: u8,
34	    /// BCM-Nummer des Echo-Pins (z. B. 24 = physischer Pin 18)
35	    pub echo_pin: u8,
36	    /// Anzahl Einzelmessungen pro Auslesung; gemeldet wird der Median.
37	    #[serde(default = "standard_messungen")]
38	    pub messungen: usize,
39	    /// Lufttemperatur in °C für die Schallgeschwindigkeit.
40	    #[serde(default = "standard_temperatur")]
41	    pub temperatur_c: f64,
42	}
43	
44	fn standard_messungen() -> usize {
45	    5
46	}
47	
48	fn standard_temperatur() -> f64 {
49	    20.0
50	}
51	
52	pub struct HcSr04 {
53	    name: String,
54	    trigger: OutputPin,
55	    echo: InputPin,
56	    messungen: usize,
57	    schall_m_pro_s: f64,
58	}
59	
60	impl HcSr04 {
61	    pub fn new(gpio: &Gpio, cfg: Config) -> Result<Self, Box<dyn Error>> {
62	        let trigger = gpio.get(cfg.trigger_pin)?.into_output_low();
63	        let mut echo = gpio.get(cfg.echo_pin)?.into_input();
64	        echo.set_interrupt(Trigger::Both, None)?;
65	
66	        Ok(Self {
67	            name: cfg.name,
68	            trigger,
69	            echo,
70	            messungen: cfg.messungen.max(1),
71	            schall_m_pro_s: schallgeschwindigkeit(cfg.temperatur_c),
72	        })
73	    }
74	
75	    /// Eine einzelne Messung, Ergebnis in cm.
76	    fn ping(&mut self) -> Result<f64, Box<dyn Error>> {
77	        // Liegengebliebene Ereignisse aus früheren Messungen verwerfen.
78	        self.echo.poll_interrupt(true, Some(Duration::ZERO))?;
79	
80	        // Trigger-Puls (>= 10 µs). Aktives Warten, weil sleep() so kurze
81	        // Zeiten nicht zuverlässig einhält.
82	        self.trigger.set_high();
83	        let start = Instant::now();
84	        while start.elapsed() < Duration::from_micros(12) {
85	            std::hint::spin_loop();
86	        }
87	        self.trigger.set_low();
88	
89	        let deadline = Instant::now() + ECHO_TIMEOUT;
90	        let steigend = self.warte_auf(Trigger::RisingEdge, deadline)?;
91	        let fallend = self.warte_auf(Trigger::FallingEdge, deadline)?;
92	
93	        let puls = fallend
94	            .timestamp
95	            .checked_sub(steigend.timestamp)
96	            .ok_or("ungültige Zeitstempel")?;
97	
98	        let cm = abstand_cm(puls, self.schall_m_pro_s);
99	        if !(MIN_CM..=MAX_CM).contains(&cm) {
100	            return Err(format!("außerhalb des Messbereichs ({cm:.1} cm)").into());
101	        }
102	        Ok(cm)
103	    }
104	
105	    fn warte_auf(&mut self, gesucht: Trigger, deadline: Instant) -> Result<Event, Box<dyn Error>> {
106	        loop {
107	            let rest = deadline.saturating_duration_since(Instant::now());
108	            if rest.is_zero() {
109	                return Err(timeout_fehler(gesucht));
110	            }
111	            match self.echo.poll_interrupt(false, Some(rest))? {
112	                Some(ev) if ev.trigger == gesucht => return Ok(ev),
113	                Some(_) => continue, // unerwartete Flanke, ignorieren
114	                None => return Err(timeout_fehler(gesucht)),
115	            }
116	        }
117	    }
118	}
119	
120	fn timeout_fehler(gesucht: Trigger) -> Box<dyn Error> {
121	    if gesucht == Trigger::RisingEdge {
122	        "kein Echo-Signal – Verkabelung, Spannungsteiler und 5-V-Versorgung prüfen".into()
123	    } else {
124	        "Echo-Puls endet nicht (Timeout)".into()
125	    }
126	}
